export const mirrorSchemaSql = "-- ══════════════════════════════════════════════════════════════════════\n-- KEYRING CUSTOMER MIRROR (run in YOUR Supabase / Neon database, once)\n-- Single-org: no organization_id column — this DB belongs to one workspace.\n-- Expiry: rows STAY, helpers FILTER (expires_at IS NULL OR > now()).\n-- Writes: ONLY the webhook applier (service_role) writes here. No client\n-- insert/update/delete policies are created on purpose.\n-- REQUIRED AFTER RUNNING: Dashboard → Settings → API → Exposed schemas →\n-- add `keyring`. Without this, PostgREST rejects every mirror write with\n-- `Invalid schema: keyring` and the applier can never land rows.\n-- ══════════════════════════════════════════════════════════════════════\n\ncreate schema if not exists keyring;\n\n-- Denormalized mirror: one row per (subject, role, permission).\n-- Powers both keyring.has(role) and keyring.can(permission) with one index.\ncreate table if not exists keyring.access (\n  subject_id text not null,\n  role_slug text not null,\n  perm_slug text not null,\n  expires_at timestamptz null,\n  updated_at timestamptz not null default now(),\n  primary key (subject_id, role_slug, perm_slug)\n);\ncreate index if not exists keyring_access_subject_perm_idx\n  on keyring.access (subject_id, perm_slug);\ncreate index if not exists keyring_access_subject_role_idx\n  on keyring.access (subject_id, role_slug);\n-- Note: no partial WHERE (expires_at …) here — now() is STABLE, not\n-- IMMUTABLE, so Postgres rejects it in index predicates (42P17). Expiry is\n-- filtered at query time inside keyring.has()/can() instead.\n\n-- Provision log: written by signup-sync.ts on success. The nightly reconcile\n-- provisions auth users ABSENT from this table — never present ones, so\n-- deliberately revoked users stay revoked. Service_role only, like access.\ncreate table if not exists keyring.provision_log (\n  subject_id text primary key,\n  role_slug text not null,\n  provisioned_at timestamptz not null default now()\n);\n\n-- ── Least privilege on the mirror ───────────────────────────────────────────\n-- RLS enabled with NO policies = deny-by-default for anon / authenticated\n-- (they hold no grants either — verified). service_role bypasses RLS, the\n-- SECURITY DEFINER helpers below run as the table owner, and the applier +\n-- signup-sync both use service_role — so nothing legitimate is blocked.\nalter table if exists keyring.access enable row level security;\nalter table if exists keyring.provision_log enable row level security;\ngrant usage on schema keyring to service_role;\ngrant all on keyring.access to service_role;\ngrant all on keyring.provision_log to service_role;\n\n-- ── Supabase helper: role check ─────────────────────────────────────────────\n-- Usage:  create policy \"teachers insert records\" on public.records\n--         for insert to authenticated with check (keyring.has('teacher'));\n-- Note: params are underscore-prefixed so they can never collide with column\n-- names (same convention as Keyring's own _subject/_perm functions).\ncreate or replace function keyring.has(_role text)\nreturns boolean\nlanguage sql stable security definer set search_path = keyring, public as $$\n  select exists (\n    select 1 from keyring.access\n    where subject_id = auth.uid()::text\n      and role_slug = _role\n      and (expires_at is null or expires_at > now())\n  )\n$$;\ngrant execute on function keyring.has(text) to authenticated, anon;\n\n-- ── Supabase helper: capability check ───────────────────────────────────────\n-- Usage:  create policy \"refund\" on public.invoices\n--         for update to authenticated using (keyring.can('invoices.refund'));\ncreate or replace function keyring.can(_perm text)\nreturns boolean\nlanguage sql stable security definer set search_path = keyring, public as $$\n  select exists (\n    select 1 from keyring.access\n    where subject_id = auth.uid()::text\n      and perm_slug = _perm\n      and (expires_at is null or expires_at > now())\n  )\n$$;\ngrant execute on function keyring.can(text) to authenticated, anon;\n\n-- ── Neon variant ────────────────────────────────────────────────────────────\n-- Neon has no auth.uid(). Set app.uid per request from your API layer after\n-- keyring.check(), then use these instead:\n--   select set_config('app.uid', 'user_abc123', true);\ncreate or replace function keyring.has_for(_subject text, _role text)\nreturns boolean\nlanguage sql stable security definer set search_path = keyring, public as $$\n  select exists (\n    select 1 from keyring.access\n    where subject_id = _subject\n      and role_slug = _role\n      and (expires_at is null or expires_at > now())\n  )\n$$;\ncreate or replace function keyring.can_for(_subject text, _perm text)\nreturns boolean\nlanguage sql stable security definer set search_path = keyring, public as $$\n  select exists (\n    select 1 from keyring.access\n    where subject_id = _subject\n      and perm_slug = _perm\n      and (expires_at is null or expires_at > now())\n  )\n$$;\n\n-- ── Example policies (adapt table/role names) ───────────────────────────────\n-- create policy \"teachers insert records\" on public.records\n-- for insert to authenticated with check (keyring.has('teacher'));\n--\n-- create policy \"clinicians read doctors\" on public.doctors\n-- for select to authenticated using (keyring.has('clinician'));\n--\n-- create policy \"refund own invoices\" on public.invoices\n-- for update to authenticated\n-- using (author_id = auth.uid() and keyring.can('invoices.refund'));\n";
export const signupTriggerSql = "-- ══════════════════════════════════════════════════════════════════════\n-- KEYRING SIGNUP TRIGGER (run in YOUR Supabase project)\n-- Alternative to Dashboard → Database → Webhooks click-path: a Postgres\n-- trigger on auth.users that POSTs every new signup to your keyring-signup\n-- Edge Function, which provisions them into the Keyring default role.\n-- ══════════════════════════════════════════════════════════════════════\n--\n-- BEFORE YOU RUN: replace these three values —\n--   <YOUR-PROJECT-REF>  e.g. agfvgcuyvydfzfjvioeu\n--   <SIGNUP_SHARED_SECRET>  the same value as the SIGNUP_SHARED_SECRET\n--     secret on your keyring-signup function (generate: python3 -c\n--     \"import secrets; print(secrets.token_urlsafe(32))\")\n--\n-- Requires pg_net (Dashboard → Database → Extensions → enable pg_net).\n-- Best-effort by design: the trigger NEVER fails a signup. If pg_net is\n-- missing, the secret mismatches, or Keyring is down, the user still gets\n-- created (holding nothing — fail-closed) and the nightly reconcile heals\n-- them. The secret lives in a config table readable only by service_role +\n-- this SECURITY DEFINER function — never in the function body, never\n-- visible to browser sessions.\n\n-- ── Config (one row) ───────────────────────────────────────────────────────\ncreate schema if not exists keyring;\n\ncreate table if not exists keyring.signup_config (\n  id integer primary key default 1 check (id = 1),\n  function_url text not null,\n  shared_secret text not null,\n  enabled boolean not null default true,\n  created_at timestamptz not null default now()\n);\nalter table keyring.signup_config enable row level security;\n-- Intentionally NO policies: service_role + SECURITY DEFINER only.\n\ninsert into keyring.signup_config (id, function_url, shared_secret)\nvalues (\n  1,\n  'https://<YOUR-PROJECT-REF>.supabase.co/functions/v1/keyring-signup',\n  '<SIGNUP_SHARED_SECRET>'\n)\non conflict (id) do update set\n  function_url = excluded.function_url,\n  shared_secret = excluded.shared_secret,\n  enabled = true;\n\n-- ── Trigger: auth.users INSERT → POST { record: { id, email } } ────────────\ncreate or replace function public.keyring_signup_hook()\nreturns trigger language plpgsql security definer set search_path = public, keyring, net as $$\ndeclare\n  v_url text;\n  v_key text;\n  v_enabled boolean;\nbegin\n  select function_url, shared_secret, enabled\n    into v_url, v_key, v_enabled\n  from keyring.signup_config where id = 1;\n  if not found or not v_enabled then return new; end if;\n  begin\n    perform net.http_post(\n      url := v_url,\n      body := jsonb_build_object(\n        'record', jsonb_build_object('id', NEW.id, 'email', NEW.email)\n      ),\n      headers := jsonb_build_object(\n        'Content-Type', 'application/json',\n        'X-Signup-Key', v_key\n      )\n    );\n  exception when others then\n    -- Best-effort only: never break a signup. Reconcile heals the gap.\n    return new;\n  end;\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_keyring_signup on auth.users;\ncreate trigger trg_keyring_signup\n  after insert on auth.users\n  for each row execute function public.keyring_signup_hook();\n\n-- ── Verify ─────────────────────────────────────────────────────────────────\n-- 1. Sign up a throwaway user (or INSERT a test row if you must — prefer a\n--    real signup via Authentication → Add user).\n-- 2. Keyring console → subjects: new UUID subject holding the default role.\n-- 3. Your DB: select * from keyring.access where subject_id = '<new-uuid>';\n-- 4. As that user: select keyring.has('<default-role-slug>'); → true.\n--\n-- To pause without dropping: update keyring.signup_config set enabled = false.\n";
export const applierTs = "// Customer applier — deploy in YOUR Supabase project as an Edge Function\n// (e.g. `keyring-applier`), then paste its URL into Keyring\n// Settings → Webhooks (or POST /api/v1/webhooks).\n//\n// What it does: verifies the Keyring HMAC signature (webhook-secret you set\n// on the endpoint) and upserts/deletes rows in keyring.access — the mirror\n// that keyring.has() / keyring.can() read inside RLS.\n//\n// Required secrets (customer project, via `supabase secrets set`):\n// KEYRING_WEBHOOK_SECRET (once-shown value from endpoint creation),\n// KEYRING_SECRET_KEY + KEYRING_URL (for snapshot refresh on grant events).\n// verify_jwt = false in your config.toml (Keyring signs with HMAC, not Supabase JWT).\nimport { createClient } from \"https://esm.sh/@supabase/supabase-js@2.49.8\";\n\nconst json = (body: unknown, status = 200) =>\n  new Response(JSON.stringify(body), { status, headers: { \"Content-Type\": \"application/json\" } });\n\nconst decodeBase64 = (input: string) => {\n  const normalized = input.replace(/-/g, \"+\").replace(/_/g, \"/\");\n  const padded = normalized + \"=\".repeat((4 - (normalized.length % 4)) % 4);\n  const raw = atob(padded);\n  return Uint8Array.from(raw, (c) => c.charCodeAt(0));\n};\n\nconst timingSafeEqual = (a: Uint8Array, b: Uint8Array) => {\n  if (a.length !== b.length) return false;\n  let diff = 0;\n  for (let i = 0; i < a.length; i++) diff |= a[i] ^ b[i];\n  return diff === 0;\n};\n\nconst verify = async (rawBody: string, headers: Headers, secret: string) => {\n  const id = headers.get(\"webhook-id\");\n  const ts = headers.get(\"webhook-timestamp\");\n  const sig = headers.get(\"webhook-signature\");\n  if (!id || !ts || !sig) return false;\n  if (Math.abs(Date.now() - Number(ts) * 1000) > 5 * 60 * 1000) return false;\n  const key = await crypto.subtle.importKey(\n    \"raw\", new TextEncoder().encode(secret), { name: \"HMAC\", hash: \"SHA-256\" }, false, [\"sign\"],\n  );\n  const expected = new Uint8Array(await crypto.subtle.sign(\"HMAC\", key, new TextEncoder().encode(`${id}.${ts}.${rawBody}`)));\n  for (const entry of sig.split(\" \").map((e) => e.trim()).filter(Boolean)) {\n    const [version, b64] = entry.split(\",\");\n    if (version !== \"v1\" || !b64) continue;\n    try {\n      if (timingSafeEqual(expected, decodeBase64(b64))) return true;\n    } catch { /* try next entry */ }\n  }\n  return false;\n};\n\ntype Delivery = {\n  id: string;\n  event: string;\n  organization_id: string;\n  data: {\n    subject?: string;\n    role?: string;\n    permission?: string;\n    expires_at?: string | null;\n  };\n};\n\nDeno.serve(async (req) => {\n try {\n  const secret = Deno.env.get(\"KEYRING_WEBHOOK_SECRET\");\n  const supabaseUrl = Deno.env.get(\"SUPABASE_URL\");\n  const serviceKey = Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\");\n  if (!secret || !supabaseUrl || !serviceKey) return json({ error: \"Missing env vars\" }, 500);\n\n  const rawBody = await req.text();\n  if (!(await verify(rawBody, req.headers, secret))) {\n    return json({ error: \"Bad signature\" }, 401);\n  }\n\n  const delivery = JSON.parse(rawBody) as Delivery;\n  const admin = createClient(supabaseUrl, serviceKey);\n  const d = delivery.data ?? {};\n\n  const refreshSubject = async (subject: string) => {\n    // Pull the snapshot (source of truth) and replace this subject's rows.\n    // Needs KEYRING_SECRET_KEY + KEYRING_URL set on this function.\n    const keyringSecret = Deno.env.get(\"KEYRING_SECRET_KEY\");\n    const keyringUrl = Deno.env.get(\"KEYRING_URL\");\n    if (!keyringSecret || !keyringUrl) {\n      throw new Error(\"Missing KEYRING_SECRET_KEY / KEYRING_URL — cannot refresh snapshot\");\n    }\n    const res = await fetch(\n      `${keyringUrl}/api/v1/subjects/access?subject=${encodeURIComponent(subject)}`,\n      { headers: { Authorization: `Bearer ${keyringSecret}` } },\n    );\n    if (!res.ok) throw new Error(`snapshot ${res.status}`);\n    const snap = await res.json() as { roles: string[]; permissions: string[] };\n    // supabase-js NEVER throws on PostgREST errors — it returns { error }.\n    // Every write below checks it: an unchecked failure returns a fake 200\n    // and the mirror silently goes stale (this exact bug cost days once).\n    const { error: deleteError } = await admin.schema(\"keyring\").from(\"access\").delete().eq(\"subject_id\", subject);\n    if (deleteError) throw new Error(`mirror delete failed: ${deleteError.message}`);\n    const rows: Array<Record<string, unknown>> = [];\n    for (const role of snap.roles ?? []) {\n      for (const perm of snap.permissions ?? []) {\n        rows.push({ subject_id: subject, role_slug: role, perm_slug: perm });\n      }\n    }\n    // Note: snapshot is role×perm pairs without per-grant expiry mapping;\n    // per-delivery expires_at (below) carries the precise value for the\n    // common single-role case. Reconcile cron refreshes the rest.\n    if (rows.length > 0) {\n      const { error: upsertError } = await admin.schema(\"keyring\").from(\"access\").upsert(rows, { onConflict: \"subject_id,role_slug,perm_slug\" });\n      if (upsertError) throw new Error(`mirror upsert failed: ${upsertError.message}`);\n    }\n    // Visible in function logs: the ONLY way to tell \"wrote nothing because\n    // snapshot was empty\" apart from \"never ran\".\n    console.log(JSON.stringify({ applier: \"refresh\", subject, roles: snap.roles ?? [], permissions: snap.permissions ?? [], rows_written: rows.length }));\n  };\n\n  switch (delivery.event) {\n    case \"grant.created\":\n    case \"grant.updated\": {\n      if (!d.subject || !d.role) return json({ ok: true, skipped: true });\n      // Precise path: fetch the role's current permissions via snapshot,\n      // then upsert with this delivery's expires_at.\n      await refreshSubject(d.subject);\n      if (d.expires_at) {\n        const { error: expiryError } = await admin.schema(\"keyring\").from(\"access\").update({ expires_at: d.expires_at }).eq(\"subject_id\", d.subject).eq(\"role_slug\", d.role);\n        if (expiryError) throw new Error(`mirror expiry update failed: ${expiryError.message}`);\n      }\n      return json({ ok: true });\n    }\n    case \"grant.deleted\":\n    case \"subject.deleted\": {\n      if (!d.subject) return json({ ok: true, skipped: true });\n      const { error: deleteError } = delivery.event === \"grant.deleted\" && d.role\n        ? await admin.schema(\"keyring\").from(\"access\").delete().eq(\"subject_id\", d.subject).eq(\"role_slug\", d.role)\n        : await admin.schema(\"keyring\").from(\"access\").delete().eq(\"subject_id\", d.subject);\n      if (deleteError) throw new Error(`mirror delete failed: ${deleteError.message}`);\n      return json({ ok: true });\n    }\n    case \"role.permissions_updated\":\n    case \"role.updated\":\n    case \"permission.updated\":\n    case \"permission.deleted\":\n      // Role-definition changes fan out to many subjects; the cheap correct\n      // move is a targeted snapshot refresh. The delivery carries the role;\n      // a full-org resync is the reconcile cron's job (nightly).\n      // For v1 we acknowledge — reconcile covers consistency.\n      return json({ ok: true, deferred_to_reconcile: true });\n    default:\n      // subject.created/updated, role.created/deleted, permission.created:\n      // no mirror rows change until a grant exists.\n      return json({ ok: true, ignored: delivery.event });\n  }\n } catch (err) {\n   // Real message in the body (not Deno's bare \"Internal Server Error\") so\n   // the dispatcher stores it and the console Response block shows the cause.\n   const message = err instanceof Error ? err.message : \"Unknown error\";\n   console.error(JSON.stringify({ applier: \"failed\", error: message }));\n   return json({ error: message }, 500);\n }\n});\n";
export const signupSyncTs = "// Customer signup sync — deploy in YOUR Supabase project as an Edge Function\n// (e.g. `keyring-signup`), then wire it to auth.users inserts via\n// Dashboard → Database → Webhooks (table auth.users, event INSERT).\n//\n// Effect: every new login is provisioned into the workspace DEFAULT role\n// (chosen in Keyring console Settings → Default role) in one call.\n// POST /api/v1/subjects/provision auto-provisions the subject (fail-closed:\n// holding nothing until granted) and is idempotent — double-fires upsert.\n// No role slug crosses the wire: the server resolves the default, so this\n// function can never choose or escalate roles.\n//\n// Required secrets (customer project, via `supabase secrets set`):\n// KEYRING_SECRET_KEY (grants.write), KEYRING_URL (e.g. https://usekeyring.dev),\n// SIGNUP_SHARED_SECRET (any random 32+ chars — also sent as the X-Signup-Key\n// header on the Database Webhook, so strangers can't mint default grants).\n// In your supabase/config.toml: [functions.keyring-signup] verify_jwt = false\n// (Database Webhooks carry no user JWT).\nDeno.serve(async (req) => {\n  const secret = Deno.env.get(\"KEYRING_SECRET_KEY\");\n  const baseUrl = Deno.env.get(\"KEYRING_URL\");\n  const shared = Deno.env.get(\"SIGNUP_SHARED_SECRET\");\n  if (!secret || !baseUrl || !shared) {\n    return new Response(JSON.stringify({ error: \"Missing KEYRING_SECRET_KEY / KEYRING_URL / SIGNUP_SHARED_SECRET\" }), {\n      status: 500, headers: { \"Content-Type\": \"application/json\" },\n    });\n  }\n  if (req.headers.get(\"X-Signup-Key\") !== shared) {\n    return new Response(JSON.stringify({ error: \"Unauthorized\" }), {\n      status: 401, headers: { \"Content-Type\": \"application/json\" },\n    });\n  }\n\n  const { record } = await req.json().catch(() => ({})) as {\n    record?: { id?: string; email?: string };\n  };\n  const subject = record?.id;\n  if (!subject) {\n    return new Response(JSON.stringify({ error: \"Expected { record: { id, email? } }\" }), {\n      status: 400, headers: { \"Content-Type\": \"application/json\" },\n    });\n  }\n\n  const res = await fetch(`${baseUrl}/api/v1/subjects/provision`, {\n    method: \"POST\",\n    headers: { Authorization: `Bearer ${secret}`, \"Content-Type\": \"application/json\" },\n    body: JSON.stringify({ subject, display_name: record?.email ?? undefined }),\n  });\n  if (!res.ok) {\n    const text = await res.text();\n    // 409 no_default_role: operator hasn't picked one yet — user holds\n    // nothing (fail-closed); reconcile heals them once a default is set.\n    return new Response(JSON.stringify({ error: `Keyring provision failed: ${res.status} ${text}` }), {\n      status: 502, headers: { \"Content-Type\": \"application/json\" },\n    });\n  }\n  const provisioned = await res.json() as { role: string; granted: boolean };\n\n  // Provision log (see schema.sql: keyring.provision_log). The nightly\n  // reconcile provisions auth users ABSENT from this table — never ones\n  // present, so deliberately revoked users stay revoked. Failures here are\n  // REPORTED, never swallowed: a missing row means reconcile misfires.\n  let provisionLog: string = \"skipped_no_env\";\n  const supabaseUrl = Deno.env.get(\"SUPABASE_URL\");\n  const serviceKey = Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\");\n  if (supabaseUrl && serviceKey) {\n    const { createClient } = await import(\"https://esm.sh/@supabase/supabase-js@2.49.8\");\n    const admin = createClient(supabaseUrl, serviceKey);\n    const { error: logError } = await admin.schema(\"keyring\").from(\"provision_log\").upsert(\n      { subject_id: subject, role_slug: provisioned.role },\n      { onConflict: \"subject_id\" },\n    );\n    provisionLog = logError ? `failed: ${logError.message}` : \"written\";\n    if (logError) console.warn(`provision_log write failed for ${subject}: ${logError.message}`);\n  } else {\n    console.warn(\"provision_log skipped: missing SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY\");\n  }\n\n  return new Response(JSON.stringify({ ok: true, subject, role: provisioned.role, granted: provisioned.granted, provision_log: provisionLog }), {\n    headers: { \"Content-Type\": \"application/json\" },\n  });\n});\n\n// Alternative (zero plumbing): skip this function and grant lazily on first\n// authenticated request from your own server:\n//   await keyring.provisionSubject({ subject: user.id, displayName: user.email });\n";
